import{_ as a,a0 as l,w as u,s as p,ao as r,I as s,x as n,a1 as e,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const w=JSON.parse('{"title":"黑客們成功地在土豆上安裝了 Linux ！ | LCTT x X-CMD","titleTemplate":false,"description":"黑客們成功地在土豆上安裝了 Linux ！ | LCTT (201601) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"黑客們成功地在土豆上安裝了 Linux ！ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"黑客們成功地在土豆上安裝了 Linux ！ | LCTT (201601) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201601/20151107 Hackers Successfully Install Linux on a Potato","title":"黑客們成功地在土豆上安裝了 Linux ！","tag":"201601","desc":""},"relativePath":"201601/20151107 Hackers Successfully Install Linux on a Potato.md","filePath":"[post].md"}'),x={name:"201601/20151107 Hackers Successfully Install Linux on a Potato.md"};function L(m,t,d,f,T,b){const o=l("Link");return u(),p("div",null,[t[15]||(t[15]=r('<h1 id="黑客們成功地在土豆上安裝了-linux" tabindex="-1">黑客們成功地在土豆上安裝了 Linux ！ <a class="header-anchor" href="#黑客們成功地在土豆上安裝了-linux" aria-label="Permalink to “黑客們成功地在土豆上安裝了 Linux ！”">​</a></h1><p>來自荷蘭阿姆斯特丹的消息稱，LinuxOnAnything.nl 網站的黑客們成功地在土豆上安裝了 Linux！這是該操作系統第一次在根用蔬菜（root vegetable）上安裝成功（LCTT 譯註：root vetetable，一語雙關，root 在 Linux 是指超級用户）。</p><p><img src="http://www.bbspot.com/Images/News_Features/2008/12/linux-potato.jpg" alt="Linux Potato"></p><p>“土豆沒有 CPU，內存和存儲器，這真的是個挑戰，” Linux On Anything (LOA) 小組的 Johan Piest 説。“顯然我們不能使用一個像 Fedora 或 Ubuntu 這些體量較大的發行版，所以我們用的是 Damn Small Linux。”</p><p>在嘗試了幾周之後，LOA 小組的的同學們弄出了一個適合土豆的 Linux 內核，這玩藝兒上面可以用 vi 來編輯小的文本文件。這個 Linux 通過一個小型的 U 盤加載到土豆上，並通過一組紅黑線以二進制的方式向這個土豆發送命令。</p><p>LOA 小組是一個不斷壯大的黑客組織的分支；這個組織致力於將 Linux 安裝到所有物體上；他們先是將 Linux 裝到Gameboy 和 iPod 等電子產品上，不過最近他們在挑戰一些高難度的東西，譬如將Linux安裝到燈泡和小狗身上！</p><p>LOA 小組在與另一個黑客小組 Stuttering Monarchs 競賽，看誰先拿到土豆這一分。“土豆是一種每個人都會接觸到的蔬菜，它的用途就像 Linux 一樣極其廣泛。無論你是想煮搗烹炸還是別的都可以” Piest 説道，“你也許認為我們完成這個挑戰是為了獲得某些好處，而我們只是追求逼格而已。”</p><p>LOA 是第一個將 Linux 安裝到一匹設德蘭矮種馬上的小組，但這五年來競爭愈演愈烈，其它黑客小組的進度已經反超了他們。</p><p>“我們本來可以成為在餅乾上面安裝 Linux 的第一個小組，但是那羣來自挪威的混蛋把我們擊敗了。” Piest 説。</p><p>第一個成功安裝了 Linux 的蔬菜是一頭捲心菜，它是由一個土耳其的一個黑客小組完成的。</p><p>（好啦——是不是已經目瞪口呆，事實上，這是一篇好幾年前的惡搞文，你看出來了嗎？哈哈哈哈）</p><hr>',12)),s("p",null,[t[1]||(t[1]=n("via: ",-1)),e(o,{href:"http://www.bbspot.com/news/2008/12/linux-on-a-potato.html"},{default:i(()=>[...t[0]||(t[0]=[n("http://www.bbspot.com/news/2008/12/linux-on-a-potato.html",-1)])]),_:1})]),s("p",null,[t[6]||(t[6]=n("作者：",-1)),e(o,{href:"briggsb@bbspot.com"},{default:i(()=>[...t[2]||(t[2]=[n("Brian Briggs",-1)])]),_:1}),t[7]||(t[7]=n(" 譯者：",-1)),e(o,{href:"https://github.com/StdioA"},{default:i(()=>[...t[3]||(t[3]=[n("StdioA",-1)])]),_:1}),t[8]||(t[8]=n(", ",-1)),e(o,{href:"https://github.com/hittlle"},{default:i(()=>[...t[4]||(t[4]=[n("hittlle",-1)])]),_:1}),t[9]||(t[9]=n(" 校對：",-1)),e(o,{href:"https://github.com/wxy"},{default:i(()=>[...t[5]||(t[5]=[n("wxy",-1)])]),_:1})]),s("p",null,[t[12]||(t[12]=n("本文由 ",-1)),e(o,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...t[10]||(t[10]=[n("LCTT",-1)])]),_:1}),t[13]||(t[13]=n(" 原創編譯，",-1)),e(o,{href:"https://linux.cn/"},{default:i(()=>[...t[11]||(t[11]=[n("Linux中國",-1)])]),_:1}),t[14]||(t[14]=n(" 榮譽推出",-1))])])}const P=a(x,[["render",L]]);export{w as __pageData,P as default};
